insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Industries","heading":"The Method Doesn''t Change With the Industry","body":"Eight sectors, one approach. What changes between them is the language buyers search in, how long they take to decide, and what a single lead is worth."}'::jsonb, 0 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'grid', 'industryGrid', 'surface', '{"eyebrow":"Where JMC Works","heading":"Eight Industries, Two Kinds of Buyer","body":"The grouping below is descriptive. It says who a business sells to, and nothing about which service it needs.","groups":[{"label":"Consumer & Community","cards":[{"title":"Home Services & Trades","body":"Trades and home service businesses that get found at the moment something breaks.","icon":"wrench","href":"/industries/home-services-trades"},{"title":"Healthcare & Wellness","body":"Practices and clinics where patients choose from a short list and book an appointment.","icon":"heart-pulse","href":"/industries/healthcare-wellness"},{"title":"Hospitality & Attractions","body":"Places people plan a visit to, from an evening out to a weekend away.","icon":"utensils","href":"/industries/hospitality-attractions"},{"title":"Professional Services","body":"Firms whose clients compare a shortlist before they ever make contact.","icon":"briefcase","href":"/industries/professional-services"}]},{"label":"Industrial & B2B","cards":[{"title":"Energy & Petrochemical","body":"Suppliers and service firms selling into plants, operators and procurement teams.","icon":"lightning","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","body":"Port, freight and marine operators whose customers are other businesses.","icon":"ship","href":"/industries/maritime-logistics"},{"title":"Commercial Construction & Infrastructure","body":"Contractors, civil firms and suppliers working on commercial and public projects.","icon":"hard-hat","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","body":"Manufacturers, service providers and suppliers in a heavily qualified supply chain.","icon":"plane","href":"/industries/aerospace-aviation"}]}],"escapeHatch":"The method doesn''t change with the industry. If yours isn''t listed, it almost certainly still applies.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 1 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'the-method', 'featureSplit', 'white', '{"align":"left","eyebrow":"Pillar","heading":"What Stays the Same, and What Doesn''t","body":"The work is the same regardless of sector. The same audit, the same technical foundation, the same content approach, the same reporting. What changes is the search language buyers use, how long they take to decide, and what a single lead is worth.\n\nThat is a deliberate position rather than a gap. A specialist charges for pattern-matching from other clients in your sector, and JMC does not claim to have that yet. What it offers instead is a method that transfers, run on two tracks depending on whether a business competes in a defined area or across markets.","tableHeadings":["Stays the same","Varies by industry"],"tableRows":[{"cells":["Audit and technical foundation","The search language buyers actually use"]},{"cells":["On-page and content approach","How long the buying cycle runs"]},{"cells":["Reporting and recap structure","What a single lead is worth"]}],"groups":[],"cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, 2 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 3 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Industry Questions","items":[{"question":"Does JMC specialise in a particular industry?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC cannot honestly offer yet. What it offers instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."},{"question":"What if an industry isn''t listed here?","answer":"The method still applies. The eight above are the sectors most common around the Houston area, not a list of what JMC is willing to work on. A visibility review is the fastest way to find out how the approach lands in yours."},{"question":"Which service fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local SEO, however many locations it runs. A business competing across markets or service lines is Traditional SEO."},{"question":"Does the industry change the price?","answer":"No. The packages are the same across every industry. Scope is what produces a custom quote, and scope is about reach and volume rather than sector."},{"question":"Does the industry change the work?","answer":"The priorities and the search language shift, sometimes a great deal. The method and the reporting do not."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Home Services & Trades","heading":"SEO for Home Services and Trades","body":"Home service searches are urgent, local, and mostly made on a phone. Getting found in that moment is a different problem from ranking for a term someone researches over a fortnight.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"coverage","label":"How buyers search","title":"Urgent and Nearby","items":["On a phone","Outside business hours","Inside a drive-time radius","Decided in minutes"]},{"kind":"coverage","label":"What it rests on","title":"Profile and Listings","items":["Map pack","Categories","Reviews"]}]}'::jsonb, 0 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":5,"eyebrow":"Who This Is For","heading":"The Trades This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"HVAC & Climate Control","icon":"gauge","body":"Demand spikes with the weather, and the searches that come with it are almost always urgent. Visibility has to already be there when the heat arrives."},{"title":"Power Washing & Exterior Cleaning","icon":"storefront","body":"A seasonal, price-comparable service where the first few businesses a homeowner finds usually get the quote requests."},{"title":"Roofing & Exterior Remodeling","icon":"home","body":"High-value jobs with a longer decision than most trades, and a spike in searches after every storm."},{"title":"Electrical & Plumbing Trades","icon":"lightning","body":"A split between emergency calls and planned work, and the two are searched for in completely different language."},{"title":"Landscaping & Tree Services","icon":"wrench","body":"Recurring and one-off work side by side, usually chosen within a tight drive-time radius."}]}'::jsonb, 1 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in the Trades","body":"Trades searches are mostly emergencies, and an emergency search behaves nothing like a considered one. Someone whose air conditioning has failed in August is on a phone, will call one of the first businesses they see, and will not open a second page of results. Storm damage does the same thing to roofing at a larger scale, and it happens with no notice.\n\nThe buying cycle is short, often minutes. That makes the map pack and the profile more valuable here than almost anywhere else, and it makes an incomplete listing an expensive problem rather than a tidy-up job. Competition is usually local, which is the good news: the field is the businesses inside the same drive-time radius, not every company in the state.","groups":[{"title":"Phone first, and often after hours","icon":"phone","body":"The searches that convert best arrive outside business hours and end in a tap on a phone number."},{"title":"Seasonal spikes with no warning","icon":"lightning","body":"Weather sets the calendar. Visibility has to be built before the spike, because there is no time to build it during one."},{"title":"Won or lost inside the map pack","icon":"map-pin","body":"For urgent work the profile carries more weight than the website, so the two have to agree with each other."}]}'::jsonb, 2 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a home services & trades business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Home Services & Trades Questions","items":[{"question":"How quickly can a trades business expect to see movement?","answer":"Local work tends to move faster than national search because the competing field is smaller, but there is no honest way to promise a date. Profile and listing corrections can show up within weeks; content and authority work is a longer arc, and the recap tells you which one you are watching each month."},{"question":"Does a service-area business without a storefront rank differently?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers rather than a pin on a map, which makes the service area definition, the categories, and consistent listings do more of the work."},{"question":"Is it worth doing SEO if most work comes from referrals?","answer":"Usually. Referrals get searched for by name before anyone calls, and a weak profile or a thin website loses jobs that were already won. That is often the cheapest fix on the list."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in home services & trades?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Healthcare & Wellness","heading":"SEO for Healthcare and Wellness Practices","body":"Patients research before they book, and they usually stop at the first practice that looks credible and close. Visibility and reputation do the work together here.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"channels","label":"How patients search","title":"By Symptom, Not Specialty","items":["What hurts, in plain words","Somewhere close by","Checked against reviews","Booked, or abandoned"]},{"kind":"coverage","label":"What it rests on","title":"Reputation and Access","items":["Reviews","Photos","Booking path"]}]}'::jsonb, 0 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"compact","columns":4,"eyebrow":"Who This Is For","heading":"Practices This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Mental & Behavioral Health Professionals","icon":"users","body":"Searched for privately and carefully, often by specialty and modality rather than by practice name."},{"title":"Private Dental & Medical Practices","icon":"heart-pulse","body":"Among the most competitive local categories anywhere, with searches split between routine care and urgent problems."},{"title":"Physical Therapy & Sports Rehab","icon":"shield-check","body":"Referral-heavy, but nearly every referral gets checked online before an appointment is made."},{"title":"Medical Spas & Wellness Clinics","icon":"star","body":"A discretionary purchase where reviews, photos and the profile carry as much weight as the website."}]}'::jsonb, 1 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"right","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Healthcare","body":"Patients search by symptom and by condition far more than by specialty. Somebody types what hurts, not the clinical name for the practitioner who fixes it, and the gap between those two vocabularies is where most practice websites lose traffic they should have had.\n\nThe cycle is short but not instant. A patient will usually look at two or three practices, check reviews on each, glance at photographs, and book the one that feels closest to both an answer and a location. That makes the profile, the reviews and the appointment path part of the SEO problem rather than separate from it. Competition is local and dense, particularly in dentistry, so the difference between the third and the first result is measured in booked appointments.","groups":[{"title":"Searched by symptom, not by specialty","icon":"search","body":"Content has to meet the language patients actually use before it can rank for it."},{"title":"Reviews are read before the site is","icon":"star","body":"Reputation and visibility are the same job here, which is why review support sits inside the packages."},{"title":"Booking friction undoes the ranking","icon":"calendar","body":"Being found first is worth little if the next step is a phone number and an answering machine."}]}'::jsonb, 2 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a healthcare & wellness business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Healthcare & Wellness Questions","items":[{"question":"Can a practice site rank without publishing medical advice?","answer":"Yes. Most of the useful traffic comes from service, condition and location pages describing what the practice treats and how a patient starts, rather than from clinical articles that need a physician to write and review them."},{"question":"How are patient reviews handled?","answer":"Packages include review request sends and replies. Nothing is fabricated or incentivised, and no review is ever written on a practice''s behalf, which would breach both the platform rules and the positioning this agency is built on."},{"question":"Does a multi-location practice need separate pages?","answer":"Usually yes. Each location needs its own profile, its own consistent listings, and enough of its own content that the two locations are not competing with each other in the same results."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in healthcare & wellness?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Hospitality & Attractions","heading":"SEO for Hospitality and Attractions","body":"Hospitality search runs on two clocks at once: someone deciding where to eat in ten minutes, and someone planning a visit six weeks out. The same business has to be visible in both.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Two clocks at once","title":"Now, and Six Weeks Out","items":["Deciding on a street","Planning a weekend","Comparing across tabs","Booking direct, or not"]},{"kind":"coverage","label":"What it rests on","title":"Listings and Detail","items":["Hours","Photos","Menus and pages"]}]}'::jsonb, 0 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Who This Is For","heading":"Places This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"RV Parks & Campground Resorts","icon":"map-pin","body":"Booked weeks ahead by people comparing sites, amenities and location across a whole region."},{"title":"Regional Venues & Event Spaces","icon":"calendar","body":"A long, considered booking with a high value, researched across many sites before anyone makes contact."},{"title":"Coastal & Waterway Attractions","icon":"ship","body":"Draws visitors from well outside the immediate area, which pulls the work beyond a single local radius."},{"title":"Boutique Hotels & Lodging","icon":"building","body":"Competing against booking platforms that outrank almost everyone, so direct visibility has to be earned in the gaps they leave."}]}'::jsonb, 1 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Hospitality","body":"Hospitality is two industries wearing one coat. A restaurant is found by someone standing on a street with ten minutes of patience, where hours, photographs and the map listing settle it before the website is opened. A venue or a hotel is found by someone planning weeks ahead, comparing options across a dozen tabs, and reading far more than a listing.\n\nThe second kind is where the reach question decides the service. A neighbourhood restaurant competes inside a few miles. A destination attraction or a wedding venue draws from a whole region and competes with businesses in other cities for the same visit, which is a different problem with a different set of pages behind it. Booking platforms sit on top of many of these results, so part of the work is finding the searches they do not dominate.","groups":[{"title":"Two clocks, one business","icon":"calendar","body":"Immediate searches and planned ones need different pages and different language."},{"title":"Photos and hours decide the click","icon":"image","body":"Profile content is not housekeeping here. It is the deciding factor on the highest-volume searches."},{"title":"Reach varies wildly by format","icon":"globe","body":"A local bar and a regional attraction are not the same engagement, which is why neither lane is assumed."}]}'::jsonb, 2 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a hospitality & attractions business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Hospitality Questions","items":[{"question":"Is this a local or a regional problem?","answer":"It depends on where guests come from. A neighbourhood restaurant is Local SEO. An attraction or venue that draws from across the region competes across markets, which points toward Traditional SEO. That question gets answered in the review rather than assumed from the category."},{"question":"Can SEO compete with the booking platforms?","answer":"Not by outranking them everywhere. It works by taking the searches they handle badly, particularly branded, specific and planning-stage queries, and by making the direct booking path the obvious one once someone has found you."},{"question":"How much does the Google Business Profile matter?","answer":"More than in almost any other sector. Hours, photographs, menu links and attributes are read directly in the results by people who never reach the website, so a stale profile costs visits outright."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in hospitality & attractions?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Professional Services","heading":"SEO for Professional Services Firms","body":"Professional services buyers research quietly and at length, then contact one or two firms. Most of the decision happens before anyone picks up a phone.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"report","label":"How clients search","title":"Quietly, Over Weeks","items":["A practice area and a place","A situation in plain words","Several visits, no contact","One or two firms called"]},{"kind":"coverage","label":"What it rests on","title":"Specificity","items":["Service pages","Named people","Clear scope"]}]}'::jsonb, 0 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"numbered","columns":3,"eyebrow":"Who This Is For","heading":"Firms This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Law Firms & Legal Services","icon":"shield-check","body":"Among the most competitive search categories that exists, with a lead value high enough to justify the fight."},{"title":"Accounting & Wealth Management","icon":"bar-chart","body":"Strongly seasonal for some services and steady for others, with a long client relationship at the end of it."},{"title":"Commercial Insurance & Staffing","icon":"briefcase","body":"Sold business to business on specificity and coverage, where a vague services page loses to a precise one."}]}'::jsonb, 1 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"right","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Professional Services","body":"Buyers here are cautious and largely invisible. They read, they compare, they check credentials, and they often visit a firm''s site several times over weeks without ever filling in a form. The consequence is that traffic and enquiries move on different timelines, and a report that only shows enquiries misses most of what changed.\n\nThe searches themselves are specific. People look for a practice area plus a place, or a situation described in plain language, and generic pages built around the firm rather than the problem do badly against them. Lead value is high, which changes the arithmetic: a small number of the right visitors is worth more than a large number of the wrong ones, and that is what the tracked keyword set should reflect.","groups":[{"title":"A long, quiet consideration","icon":"clipboard-check","body":"Several visits before contact is normal, so early traffic movement matters before enquiries do."},{"title":"Practice area plus place","icon":"search","body":"Specific pages for specific services beat one broad page that tries to hold all of them."},{"title":"Credibility is a ranking factor in practice","icon":"shield-check","body":"Named people, real detail and clear scope outperform anonymous copy for both readers and search engines."}]}'::jsonb, 2 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a professional services business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Professional Services Questions","items":[{"question":"Why do enquiries lag behind traffic in this sector?","answer":"Because the decision takes weeks and involves several visits. That is normal here, and it is one of the reasons the recap reports what changed in visibility as well as what came through the form."},{"question":"Does a firm need a page per service?","answer":"Generally yes. Clients search for a specific practice area, and a single page trying to cover six of them tends to rank for none of them well."},{"question":"Are results in a competitive practice area realistic?","answer":"In the most contested categories, progress usually starts on more specific searches rather than the broadest term. That is a slower route but a real one, and the reporting is explicit about which stage the work is at."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in professional services?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/professional-services';
